def active_vector_meet(active_members, shard_frontiers):
    result = [MAX_EPOCH, MAX_EPOCH]
    has_active = False
    for i in range(NUM_SHARDS):
        if active_members[i]:
            result = vector_meet(result, shard_frontiers[i])
            has_active = True
    return result if has_active else [0, 0]

# State variables

def cas_lease(self, aggregator_id, current_token, new_token):
        if self.fence_token == current_token:
            self.leader_lease = aggregator_id
            self.fence_token = new_token
            return True
        return False

def write_frontier(self, token, frontier):
        if token >= self.fence_token:
            if vector_ge(frontier, self.published_frontier):
                self.published_frontier = frontier
                self.fence_token = token
                return True
        return False
